const r = await tools.exec_command({cmd:"pwd && rg --files .github/workflows tools docs/runbooks docs/operations docs/skill-profiles | head -n 120","workdir":"/Users/cooper/Projects/taxkit","max_output_tokens":8000});
text(r.output);
text(await tools.exec_command({cmd:"sed -n '1,180p' docs/README.md","workdir":"/Users/cooper/Projects/taxkit","max_output_tokens":7000}));
text(await tools.exec_command({cmd:"rg --files .github/workflows packages/infrastructure/src | head -n 80","workdir":"/Users/cooper/Projects/common-practice","max_output_tokens":5000}));

const results = await Promise.allSettled([
  tools.exec_command({cmd:"python3 -c 'import json; p=json.load(open(\"package.json\")); print(json.dumps({\"scripts\":p.get(\"scripts\"),\"patchedDependencies\":p.get(\"patchedDependencies\")},indent=2))'","workdir":"/Users/cooper/Projects/taxkit","max_output_tokens":9000}),
  tools.exec_command({cmd:"python3 -c 'import json; p=json.load(open(\"package.json\")); print(json.dumps({\"scripts\":p.get(\"scripts\"),\"patchedDependencies\":p.get(\"patchedDependencies\")},indent=2))'","workdir":"/Users/cooper/Projects/common-practice","max_output_tokens":6500}),
  tools.exec_command({cmd:"nl -ba .github/workflows/checks.yml; nl -ba .github/workflows/production.yml; nl -ba .github/workflows/preview.yml","workdir":"/Users/cooper/Projects/common-practice","max_output_tokens":14000}),
  tools.exec_command({cmd:"nl -ba docs/skills.md | sed -n '1,130p'; nl -ba docs/skill-profiles/docs-maintainer.md | sed -n '1,90p'","workdir":"/Users/cooper/Projects/taxkit","max_output_tokens":9000})
]);
for (let i=0;i<results.length;i++) text({i,...(results[i].status==="fulfilled"?results[i].value:{error:String(results[i].reason)})});

const results = await Promise.allSettled([
  tools.exec_command({cmd:"nl -ba .github/workflows/quality.yml | sed -n '1,210p'; nl -ba .github/workflows/docs-deployment-workflow-receipts.yml | sed -n '1,180p'; for file in .github/workflows/docs-preview.yml .github/workflows/docs-production.yml .github/workflows/docs-preview-teardown.yml .github/workflows/docs-production-hosted-verify.yml; do nl -ba \"$file\" | sed -n '1,125p'; done","workdir":"/Users/cooper/Projects/taxkit","max_output_tokens":13500}),
  tools.exec_command({cmd:"nl -ba packages/infrastructure/src/secrets.ts; nl -ba alchemy.run.ts; rg -n '^##|^###|Doppler|commit|approval|receipt|verification|rollback|unpatched|dry-run|destroy' docs/runbooks/deployment.md | head -n 100","workdir":"/Users/cooper/Projects/common-practice","max_output_tokens":7500}),
  tools.exec_command({cmd:"rg -n 'tools/(docs-deployment|governance|evals|quality-workflow|documentation)|check:harness|check:hgi|release:check|release:present|docs:catalogue|owner-policy|acceptanceRecord|acceptedCatalogue' --glob '!bun.lock' --glob '!docs/evidence/**' --glob '!docs/documentation-audit/**' --glob '!docs/exec-plans/completed/**' --glob '!patches/**' --glob '!node_modules/**' --glob '!CONTEXT.md' --glob '!docs/product-specs/**' --glob '!tools/docs-deployment/**' --glob '!tools/governance/**' --glob '!tools/evals/**' --glob '!tools/quality-workflow/**' . | head -n 200","workdir":"/Users/cooper/Projects/taxkit","max_output_tokens":10000}),
  tools.exec_command({cmd:"rg --files packages/scripts packages/docs-content packages/docs-fumadocs tools/documentation tools/docs-deployment tools/governance tools/evals tools/quality-workflow | sort | tail -n 140","workdir":"/Users/cooper/Projects/taxkit","max_output_tokens":6500})
]);
for (let i=0;i<results.length;i++) text({i,...(results[i].status==="fulfilled"?results[i].value:{error:String(results[i].reason)})});

const results = await Promise.allSettled([
  tools.exec_command({cmd:"nl -ba packages/infrastructure/src/secrets.ts; rg -n '^##|^###|native.*(deploy|plan)|receipt|unpatched|rollback|Doppler' docs/runbooks/deployment.md | head -n 80","workdir":"/Users/cooper/Projects/common-practice","max_output_tokens":4000}),
  tools.exec_command({cmd:"rg -n 'tools/(docs-deployment|governance|evals|quality-workflow|documentation)|check:harness|check:hgi|release:check|release:present|docs:catalogue' packages apps alchemy*.ts turbo.json tsconfig*.json knip*.json --glob '!**/.source/**' --glob '!**/dist/**' --glob '!**/node_modules/**' --glob '!**/*.md' | head -n 170","workdir":"/Users/cooper/Projects/taxkit","max_output_tokens":7500}),
  tools.exec_command({cmd:"rg --files packages/scripts/src packages/docs-content/src packages/docs-fumadocs/src packages/content/src | head -n 160; python3 -c 'import json; paths=[\"packages/scripts/package.json\",\"packages/docs-content/package.json\",\"packages/docs-fumadocs/package.json\",\"packages/sdk/typescript/package.json\",\"packages/api/http/package.json\",\"apps/web/package.json\"]; [print(p, json.dumps({k:json.load(open(p)).get(k) for k in (\"scripts\",\"exports\")},indent=2)) for p in paths]'","workdir":"/Users/cooper/Projects/taxkit","max_output_tokens":9000}),
  tools.exec_command({cmd:"rg -n 'acceptance|receipt|sourceHash|policy|catalogue|content|generate|proof' tools/documentation/catalogue.policy.ts tools/documentation/catalogue.build.ts tools/documentation/catalogue.runtime.ts packages/docs-content/src/* packages/docs-content/content.config.ts packages/docs-content/source.config.ts 2>/dev/null | head -n 130","workdir":"/Users/cooper/Projects/taxkit","max_output_tokens":5000})
]);
for (let i=0;i<results.length;i++) text({i,...(results[i].status==="fulfilled"?results[i].value:{error:String(results[i].reason)})});

